add_action( 'woocommerce_cart_loaded_from_session', 'perfectpixel_sort_cart_items_alphabetically' );

function perfectpixel_sort_cart_items_alphabetically( $cart ) {
	if ( count( $cart->cart_contents ) < 2 ) {
		return;
	}
	uasort(
		$cart->cart_contents,
		static function ( $a, $b ) {
			return strcasecmp( $a['data']->get_name(), $b['data']->get_name() );
		}
	);
}
